#include <bits/stdc++.h>
using namespace std;

long long modPow(long long base, int exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long nCr(int n, int r, long long mod, vector<long long>& fact, vector<long long>& invFact) {
    return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long mod = 998244353;
    int n;
    long long k;
    cin >> n >> k;

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
    invFact[n] = modPow(fact[n], (int)mod - 2, mod);
    for (int i = n - 1; i >= 1; i--) {
        invFact[i] = ((i + 1) * invFact[i + 1]) % mod;
    }

    if (k == 0) {
        cout << fact[n] << "\n";
        return 0;
    }

    int r = n - (int)k;
    long long ans = 0;
    int p = 1;
    for (int i = 0; i < r; i++) {
        long long term = (p * nCr(r, i, mod, fact, invFact)) % mod;
        term = (term * modPow(r - i, n, mod)) % mod;
        ans = (ans + term) % mod;
        p *= -1;
    }
    long long result = (2 * nCr(n, r, mod, fact, invFact) * ans) % mod;
    cout << result << "\n";

    return 0;
}
